<script setup lang="ts">
import { useGameStore } from '../stores/game'
const store=useGameStore();const items=[{id:'first-win',name:'初次中奖',desc:'累计中奖 1 次',goal:1,reward:100,progress:()=>store.game.statistics.totalWon},{id:'lucky-star',name:'幸运新星',desc:'累计中奖 10 次',goal:10,reward:500,progress:()=>store.game.statistics.totalWon},{id:'scratch-master',name:'刮奖达人',desc:'累计刮奖 100 次',goal:100,reward:1000,progress:()=>store.game.statistics.totalScratched},{id:'tycoon',name:'彩票大亨',desc:'累计获得 100,000 金币',goal:100000,reward:5000,progress:()=>store.game.statistics.totalEarned},{id:'777',name:'777 收藏家',desc:'获得一次幸运 777 彩票',goal:1,reward:2000,progress:()=>store.game.tickets.some(t=>t.gameId==='lucky777'&&t.isWinner)?1:0},{id:'automation',name:'自动化大师',desc:'自动化天赋达到 Lv.8',goal:8,reward:10000,progress:()=>store.game.talents.automation}]
function claim(item:typeof items[number]){if(item.progress()<item.goal||store.game.achievements[item.id]?.claimed)return;store.claimAchievement(item.id,item.reward,`成就奖励：${item.name}`)}
</script>
<template><div class="page"><div class="page-heading"><div><span class="eyebrow">MILESTONES & RECORDS</span><h1>成就与经营统计</h1><p>每一次刮奖、每一次成长，都值得被记录。</p></div></div><div class="stats-grid"><div class="panel record-stat"><small>累计刮奖</small><b>{{store.game.statistics.totalScratched}}</b></div><div class="panel record-stat"><small>累计中奖</small><b>{{store.game.statistics.totalWon}}</b></div><div class="panel record-stat"><small>累计收入</small><b>{{store.game.statistics.totalEarned.toLocaleString()}}</b></div><div class="panel record-stat"><small>累计支出</small><b>{{store.game.statistics.totalSpent.toLocaleString()}}</b></div></div><div class="achievement-list"><article v-for="item in items" :key="item.id" class="panel achievement"><span class="achievement-icon">🏅</span><div class="achievement-info"><b>{{item.name}}</b><small>{{item.desc}}</small><div class="progress-line"><span :style="{width:`${Math.min(100,item.progress()/item.goal*100)}%`}"/></div></div><div class="achievement-action"><b>+{{item.reward.toLocaleString()}} 🪙</b><button class="btn" :class="item.progress()>=item.goal?'primary':'secondary'" :disabled="item.progress()<item.goal||store.game.achievements[item.id]?.claimed" @click="claim(item)">{{store.game.achievements[item.id]?.claimed?'已领取':item.progress()>=item.goal?'领取奖励':'进行中'}}</button></div></article></div><section class="panel transaction-panel"><div class="section-head"><h2>最近交易记录</h2><span class="muted">最多保留 100 条</span></div><div v-for="tx in store.game.transactions.slice(0,8)" :key="tx.id" class="transaction"><span>{{tx.reason}}</span><small>{{new Date(tx.createdAt).toLocaleString()}}</small><b :class="tx.type">{{tx.type==='income'?'+':'-'}}{{tx.amount.toLocaleString()}}</b></div><div v-if="!store.game.transactions.length" class="empty">还没有交易记录</div></section></div></template>